// Shared helpers for the static site. Each page fetches its own JSON from
// docs/data/*.json (generated by scripts/build_data.py from registry/*.yaml).

async function loadJSON(path) {
  const res = await fetch(path, { cache: "no-store" });
  if (!res.ok) throw new Error(`Failed to load ${path}: ${res.status}`);
  return res.json();
}

function el(tag, attrs = {}, children = []) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === "text") node.textContent = v;
    else if (k === "html") node.innerHTML = v;
    else node.setAttribute(k, v);
  }
  for (const child of [].concat(children)) {
    if (child) node.appendChild(child);
  }
  return node;
}

function emptyState(msg) {
  return el("p", { class: "empty-state", text: msg });
}

// ---- People (Who's Who) ----
async function renderPeople(containerId) {
  const container = document.getElementById(containerId);
  try {
    const people = await loadJSON("data/people.json");
    if (!people.length) {
      container.appendChild(emptyState("Who's who list coming soon."));
      return;
    }
    const grid = el("div", { class: "grid" });
    for (const p of people) {
      const img = el("img", {
        src: p.image ? `assets/people/${p.image}` : "assets/people/placeholder.svg",
        alt: p.name || "",
      });
      const links = el("div", { class: "meta" });
      if (p.links) {
        for (const [label, url] of Object.entries(p.links)) {
          links.appendChild(el("a", { href: url, text: label, target: "_blank", rel: "noopener" }));
          links.appendChild(document.createTextNode(" "));
        }
      }
      const card = el("div", { class: "card person-card" }, [
        img,
        el("h3", { text: p.name || "Unnamed" }),
        el("div", { class: "role", text: p.role || "" }),
        links,
      ]);
      grid.appendChild(card);
    }
    container.appendChild(grid);
  } catch (e) {
    container.appendChild(emptyState("Could not load who's who data."));
    console.error(e);
  }
}

// ---- Resources ----
async function renderResources(containerId) {
  const container = document.getElementById(containerId);
  try {
    const categories = await loadJSON("data/resources.json");
    if (!categories.length) {
      container.appendChild(emptyState("Resources coming soon."));
      return;
    }
    for (const cat of categories) {
      const section = el("section", { class: "resource-category" });
      section.appendChild(el("h2", { text: cat.category }));
      for (const item of cat.items || []) {
        section.appendChild(
          el("div", { class: "card" }, [
            el("h3", {}, [el("a", { href: item.url, text: item.title, target: "_blank", rel: "noopener" })]),
            item.note ? el("div", { class: "meta", text: item.note }) : null,
          ])
        );
      }
      container.appendChild(section);
    }
  } catch (e) {
    container.appendChild(emptyState("Could not load resources data."));
    console.error(e);
  }
}

// ---- Agenda ----
async function renderAgenda(containerId) {
  const container = document.getElementById(containerId);
  try {
    const days = await loadJSON("data/agenda.json");
    if (!days.length) {
      container.appendChild(
        emptyState("Agenda not published yet — check back soon.")
      );
      return;
    }
    for (const day of days) {
      const section = el("div", { class: "agenda-day" });
      section.appendChild(el("h2", { text: day.date ? `${day.label || "Day"} — ${day.date}` : (day.label || "Day") }));
      for (const item of day.items || []) {
        section.appendChild(
          el("div", { class: "agenda-item" }, [
            el("div", { class: "time", text: item.time || "" }),
            el("div", {}, [
              el("strong", { text: item.title || "" }),
              item.speaker ? el("div", { class: "meta", text: item.speaker }) : null,
              item.description ? el("p", { text: item.description }) : null,
            ]),
          ])
        );
      }
      container.appendChild(section);
    }
  } catch (e) {
    container.appendChild(emptyState("Could not load agenda data."));
    console.error(e);
  }
}

// ---- Submissions / Projects ----
async function renderSubmissions(containerId) {
  const container = document.getElementById(containerId);
  try {
    const subs = await loadJSON("data/submissions.json");
    if (!subs.length) {
      container.appendChild(emptyState("No projects submitted yet — be the first!"));
      return;
    }
    for (const s of subs) {
      const links = el("div", { class: "meta" }, [
        el("a", { href: s.repo_url, text: "Code", target: "_blank", rel: "noopener" }),
        document.createTextNode(" · "),
        el("a", { href: s.hf_model_url, text: "Model (Hugging Face)", target: "_blank", rel: "noopener" }),
      ]);
      container.appendChild(
        el("div", { class: "card" }, [
          el("h3", { text: s.title || s.slug }),
          el("div", { class: "meta", text: (s.team || []).join(", ") }),
          el("p", { text: s.description || "" }),
          links,
        ])
      );
    }
  } catch (e) {
    container.appendChild(emptyState("Could not load submissions data."));
    console.error(e);
  }
}
